    hdiv = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    vdiv = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    def spans(n, divs):
        out, start = [], 0
        for d in divs:
            if d > start:
                out.append((start, d))
            start = d + 1
        if start < n:
            out.append((start, n))
        return out
    rows, cols = spans(h, hdiv), spans(w, vdiv)
    # A small colored key in the first panel gives the fill color for each row.
    colors = []
    for r0, r1 in rows:
        vals = [grid[r][c] for r in range(r0, r1) for c in range(cols[0][0], cols[0][1]) if grid[r][c] != 0]
        colors.append(max(set(vals), key=vals.count))
    # The lone non-key pattern panel is the stencil to replicate in every panel.
    pattern = None
